package cn.iocoder.yudao.module.platform.training;

import cn.iocoder.yudao.framework.common.exception.ServiceException;
import cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder;
import cn.iocoder.yudao.module.platform.authz.CurrentPost;
import cn.iocoder.yudao.module.platform.org.PostSnapshot;
import cn.iocoder.yudao.module.platform.operations.OperationsGuard;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import java.time.*;
import java.util.*;
import static cn.iocoder.yudao.module.platform.training.TrainingModel.*;

@Service
public class TrainingCatalog {
    private final JdbcTemplate jdbc;private final OperationsGuard guard;private final TrainingFiles files;
    private final CurrentPost posts;private final ObjectMapper json;private final TransactionTemplate tx;
    public TrainingCatalog(JdbcTemplate jdbc,OperationsGuard guard,TrainingFiles files,CurrentPost posts,ObjectMapper json,PlatformTransactionManager tm){this.jdbc=jdbc;this.guard=guard;this.files=files;this.posts=posts;this.json=json;tx=new TransactionTemplate(tm);}
    String encode(Object o){try{return json.writeValueAsString(o);}catch(Exception e){throw new ServiceException(400,"课程内容无效");}}
    Course decode(Object value){try{return json.readValue(value.toString(),Course.class);}catch(Exception e){throw new ServiceException(400,"课程内容无法读取");}}
    Map<String,Object> row(String id,long tenant,boolean lock){var rows=jdbc.queryForList("SELECT * FROM pf_training_course WHERE id=? AND tenant_id=?"+(lock?" FOR UPDATE":""),id,tenant);if(rows.isEmpty())throw new ServiceException(404,"课程不存在");return rows.get(0);}
    private void audit(OperationsGuard.Actor a,String object,String action,long revision,String reason){jdbc.update("INSERT INTO pf_training_audit(tenant_id,actor_id,object_id,action,revision,detail) VALUES(?,?,?,?,?,?)",a.tenantId(),a.userId(),object,action,revision,reason==null?"":reason);}
    public Map<String,Object> detail(String id){var a=guard.require();var r=row(id,a.tenantId(),false);var out=new LinkedHashMap<String,Object>();out.put("id",id);out.put("revision",r.get("revision"));out.put("state",r.get("state"));out.put("reviewState",r.get("review_state"));out.put("activeRelease",r.get("active_release"));out.put("content",decode(r.get("draft")));out.put("history",jdbc.queryForList("SELECT actor_id::text AS actor_id,action,revision,detail,created_at FROM pf_training_audit WHERE tenant_id=? AND object_id=? ORDER BY id DESC LIMIT 30",a.tenantId(),id));return out;}
    public Map<String,Object> courses(String keyword,int page){var a=guard.require();check(page>0&&page<=10000,"页码无效");check(keyword==null||keyword.length()<=100,"关键词过长");String kw="%"+(keyword==null?"":keyword.replace("%","\\%").replace("_","\\_"))+"%";
        var out=jdbc.queryForList("SELECT id,revision,state,review_state,active_release,draft->>'title' AS title,draft->>'category' AS category,draft->>'lecturer' AS lecturer,jsonb_array_length(draft->'lessons') AS lesson_count,updated_at FROM pf_training_course WHERE tenant_id=? AND draft->>'title' ILIKE ? ORDER BY updated_at DESC LIMIT 50 OFFSET ?",a.tenantId(),kw,(page-1)*50);
        return Map.of("list",out,"total",jdbc.queryForObject("SELECT COUNT(*) FROM pf_training_course WHERE tenant_id=? AND draft->>'title' ILIKE ?",Long.class,a.tenantId(),kw));}
    public List<Map<String,Object>> organizations(){var a=guard.require();return jdbc.queryForList("SELECT o.dept_id::text AS id,d.name FROM pf_org_unit o JOIN system_dept d ON d.id=o.dept_id WHERE d.tenant_id=? AND d.deleted=0 AND d.status=0 AND o.kind='ORG' AND o.status='ACTIVE' ORDER BY d.name",a.tenantId());}
    private void validate(Course c,long tenant,boolean publishing){
        check(c!=null,"请填写课程内容");text(c.title(),40,"课程名称");check(CATEGORIES.contains(c.category()),"请选择课程分类");
        check(c.summary()!=null&&c.summary().length()<=200,"课程简介最多200字");check(c.objective()!=null&&c.objective().length()<=1000,"学习目标最多1000字");check(c.lecturer()!=null&&c.lecturer().length()<=80,"内容负责人最多80字");
        check(list(c.roles()).size()<=ROLES.size()&&ROLES.containsAll(list(c.roles())),"岗位范围无效");check(list(c.organizationIds()).size()<=10000&&list(c.userIds()).size()<=10000,"开放范围过大");
        for(String org:list(c.organizationIds())){check(org!=null&&org.matches("[0-9]+"),"组织编号无效");check(Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM pf_org_unit o JOIN system_dept d ON d.id=o.dept_id WHERE o.dept_id=? AND d.tenant_id=? AND d.deleted=0 AND d.status=0 AND o.kind='ORG' AND o.status='ACTIVE')",Boolean.class,Long.parseLong(org),tenant)),"组织不可用");}
        for(String user:list(c.userIds())){check(user!=null&&user.matches("[0-9]+"),"人员编号无效");check(Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM system_users WHERE id=? AND tenant_id=? AND deleted=0 AND status=0)",Boolean.class,Long.parseLong(user),tenant)),"指定人员不可用");}
        Instant start=time(c.opensAt()),end=time(c.closesAt());check(start==null||end==null||end.isAfter(start),"结束时间必须晚于开始时间");
        check(list(c.lessons()).size()<=500&&list(c.attachments()).size()<=100,"课程内容数量过多");Set<String> ids=new HashSet<>();
        for(var lesson:list(c.lessons())){check(lesson!=null,"课时内容无效");text(lesson.id(),40,"课时编号");check(ids.add(lesson.id()),"课时编号重复");text(lesson.title(),80,"课时名称");text(lesson.chapter(),80,"章节名称");check(lesson.completionPercent()>=50&&lesson.completionPercent()<=100,"完成阈值应为50至100");check(list(lesson.attachments()).size()<=50,"每节最多50份资料");
            if(lesson.mainVersionId()!=null&&!lesson.mainVersionId().isBlank()){var v=files.version(lesson.mainVersionId(),tenant);if(publishing){check("READY".equals(v.get("state")),"主课件尚未可用："+lesson.title());check(v.get("media_key")!=null||v.get("preview_key")!=null,"主课件必须可播放或预览："+lesson.title());}}
            else check(!publishing,"请设置主课件："+lesson.title());
            attachments(lesson.attachments(),tenant,publishing);
        }
        attachments(c.attachments(),tenant,publishing);
        if(c.coverVersionId()!=null&&!c.coverVersionId().isBlank()){var v=files.version(c.coverVersionId(),tenant);check(Set.of("jpg","jpeg","png","webp").contains(v.get("extension")),"封面必须为图片");if(publishing)check("READY".equals(v.get("state")),"封面尚未可用");}
        if(publishing){text(c.lecturer(),80,"内容负责人");check(!list(c.roles()).isEmpty(),"请选择可学习岗位");check(c.allOrganizations()||!list(c.organizationIds()).isEmpty(),"请选择可学习组织");check(!list(c.lessons()).isEmpty(),"课程至少需要一个可用课时");}
    }
    private void attachments(List<Attachment> attachments,long tenant,boolean publishing){Set<String> ids=new HashSet<>();for(var a:list(attachments)){check(a!=null&&a.versionId()!=null&&ids.add(a.versionId()),"附件编号无效或重复");var v=files.version(a.versionId(),tenant);if(publishing){check("READY".equals(v.get("state")),"附件尚未可用："+v.get("name"));check(v.get("preview_key")!=null||a.download(),"该附件仅支持下载，请明确允许下载："+v.get("name"));}}}
    static Instant time(String t){if(t==null||t.isBlank())return null;try{return Instant.parse(t);}catch(Exception e){throw new ServiceException(400,"开放时间格式无效");}}
    public Map<String,Object> save(String course,Save input){var a=guard.require();check(input!=null,"请填写课程");String courseId=course==null?id():course;
        tx.executeWithoutResult(status->{files.lockCatalog(a.tenantId());validate(input.content(),a.tenantId(),false);if(course==null){jdbc.update("INSERT INTO pf_training_course(id,tenant_id,draft,created_by) VALUES(?,?,?::jsonb,?)",courseId,a.tenantId(),encode(input.content()),a.userId());audit(a,courseId,"CREATE",0,"");}
        else{var r=row(courseId,a.tenantId(),true);long revision=((Number)r.get("revision")).longValue();check(input.expectedRevision()!=null&&input.expectedRevision()==revision,"课程已被其他人修改，请刷新后重试");jdbc.update("UPDATE pf_training_course SET draft=?::jsonb,revision=revision+1,review_state='DRAFT',updated_at=now() WHERE id=? AND tenant_id=?",encode(input.content()),courseId,a.tenantId());audit(a,courseId,"SAVE",revision+1,"");}});return detail(courseId);}
    public Map<String,Object> act(String id,String action,Action in){var a=guard.require();check(in!=null,"请选择操作");check(in.reason()==null||in.reason().length()<=500,"原因最多500字");
        tx.executeWithoutResult(status->{files.lockCatalog(a.tenantId());var r=row(id,a.tenantId(),true);long revision=((Number)r.get("revision")).longValue();check(revision==in.expectedRevision(),"课程版本已变化，请刷新后重试");Course c=decode(r.get("draft"));
            switch(action){
                case "submit" -> {validate(c,a.tenantId(),true);check(Set.of("DRAFT","REJECTED").contains(r.get("review_state")),"当前状态不可提交审核");jdbc.update("UPDATE pf_training_course SET review_state='PENDING',revision=revision+1,updated_at=now() WHERE id=? AND tenant_id=?",id,a.tenantId());}
                case "reject" -> {text(in.reason(),500,"退回原因");check("PENDING".equals(r.get("review_state")),"仅待审核课程可以退回");jdbc.update("UPDATE pf_training_course SET review_state='REJECTED',revision=revision+1,updated_at=now() WHERE id=? AND tenant_id=?",id,a.tenantId());}
                case "publish" -> {check("PENDING".equals(r.get("review_state")),"请先提交审核再发布");validate(c,a.tenantId(),true);int number=jdbc.queryForObject("SELECT COALESCE(MAX(release_no),0)+1 FROM pf_training_release WHERE tenant_id=? AND course_id=?",Integer.class,a.tenantId(),id);String release=id();jdbc.update("INSERT INTO pf_training_release(id,tenant_id,course_id,release_no,content,published_by) VALUES(?,?,?,?,?::jsonb,?)",release,a.tenantId(),id,number,encode(c),a.userId());jdbc.update("UPDATE pf_training_course SET state='PUBLISHED',active_release=?,review_state='PUBLISHED',revision=revision+1,updated_at=now() WHERE id=? AND tenant_id=?",release,id,a.tenantId());}
                case "withdraw" -> {text(in.reason(),500,"下架原因");check("PUBLISHED".equals(r.get("state")),"课程尚未发布");jdbc.update("UPDATE pf_training_course SET state='WITHDRAWN',review_state='DRAFT',revision=revision+1,updated_at=now() WHERE id=? AND tenant_id=?",id,a.tenantId());}
                default -> throw new ServiceException(400,"不支持的课程操作");
            }audit(a,id,action.toUpperCase(Locale.ROOT),revision+1,in.reason());
        });return detail(id);}
    public List<String> issues(String id){var a=guard.require();Course c=decode(row(id,a.tenantId(),false).get("draft"));try{validate(c,a.tenantId(),true);return List.of();}catch(ServiceException e){return List.of(e.getMessage());}}
    public Map<String,Object> materialDetail(String version){var a=guard.require();var v=new LinkedHashMap<>(files.version(version,a.tenantId()));v.remove("original_key");v.remove("media_key");v.remove("preview_key");v.remove("poster_key");v.put("versions",jdbc.queryForList("SELECT id,version_no,state,created_at FROM pf_training_material_version WHERE tenant_id=? AND material_id=? ORDER BY version_no DESC",a.tenantId(),v.get("material_id")));v.put("references",files.materialReferences(v.get("material_id").toString(),a.tenantId()));return v;}
    public List<Map<String,Object>> learnerCourses(String keyword){PostSnapshot p=posts.require();long tenant=tenant();List<Map<String,Object>> result=new ArrayList<>();String kw=keyword==null?"":keyword.trim();check(kw.length()<=100,"关键词过长");
        for(var r:jdbc.queryForList("SELECT c.id,c.active_release,r.release_no,r.content FROM pf_training_course c JOIN pf_training_release r ON r.id=c.active_release AND r.tenant_id=c.tenant_id WHERE c.tenant_id=? AND c.state='PUBLISHED' ORDER BY c.updated_at DESC",tenant)){Course c=decode(r.get("content"));if(allows(c,p)&& (c.title()+c.category()+c.summary()).contains(kw)){var m=summary(r.get("id").toString(),r.get("active_release").toString(),c,tenant,p);result.add(m);}}return result;}
    boolean allows(Course c,PostSnapshot p){Instant now=Instant.now();Instant start=time(c.opensAt()),end=time(c.closesAt());return ROLES.contains(p.roleCode())&&list(c.roles()).contains(p.roleCode())&&(c.allOrganizations()||list(c.organizationIds()).contains(String.valueOf(p.orgId())))&&(list(c.userIds()).isEmpty()||list(c.userIds()).contains(String.valueOf(p.userId())))&&(start==null||!now.isBefore(start))&&(end==null||now.isBefore(end));}
    long tenant(){Long t=TenantContextHolder.getTenantId();if(t==null)throw new ServiceException(401,"请先登录");return t;}
    Course released(String course,PostSnapshot p,long tenant){var r=row(course,tenant,false);if(!"PUBLISHED".equals(r.get("state")))throw new ServiceException(404,"课程暂未开放");var release=jdbc.queryForMap("SELECT content FROM pf_training_release WHERE id=? AND tenant_id=?",r.get("active_release"),tenant);Course c=decode(release.get("content"));if(!allows(c,p))throw new ServiceException(403,"当前工作身份无此课程权限");return c;}
    public Map<String,Object> learnerDetail(String course){PostSnapshot p=posts.require();long tenant=tenant();Course c=released(course,p,tenant);String release=row(course,tenant,false).get("active_release").toString();var m=summary(course,release,c,tenant,p);var lessons=new ArrayList<Map<String,Object>>();for(var l:list(c.lessons())){var v=files.version(l.mainVersionId(),tenant);var lesson=new LinkedHashMap<String,Object>();lesson.put("id",l.id());lesson.put("title",l.title());lesson.put("chapter",l.chapter());lesson.put("duration",v.get("duration"));lesson.put("extension",v.get("extension"));lesson.put("completed",complete(tenant,p,course,l));lesson.put("attachments",attachmentView(l.attachments(),tenant));lessons.add(lesson);}m.put("lessons",lessons);m.put("attachments",attachmentView(c.attachments(),tenant));m.put("objective",c.objective());return m;}
    private Map<String,Object> summary(String id,String release,Course c,long tenant,PostSnapshot p){var m=new LinkedHashMap<String,Object>();m.put("id",id);m.put("releaseId",release);m.put("title",c.title());m.put("category",c.category());m.put("lecturer",c.lecturer());m.put("summary",c.summary());m.put("coverVersionId",c.coverVersionId());m.put("lessons",list(c.lessons()).size());long done=list(c.lessons()).stream().filter(l->complete(tenant,p,id,l)).count();m.put("completed",done);m.put("percent",list(c.lessons()).isEmpty()?0:(int)Math.round(100.0*done/list(c.lessons()).size()));return m;}
    private boolean complete(long tenant,PostSnapshot p,String course,Lesson lesson){return Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM pf_training_progress WHERE tenant_id=? AND org_id=? AND user_id=? AND course_id=? AND lesson_id=? AND version_id=? AND completed)",Boolean.class,tenant,p.orgId(),p.userId(),course,lesson.id(),lesson.mainVersionId()));}
    private List<Map<String,Object>> attachmentView(List<Attachment> attachments,long tenant){var out=new ArrayList<Map<String,Object>>();for(var a:list(attachments)){var v=files.version(a.versionId(),tenant);var m=new LinkedHashMap<String,Object>();m.put("versionId",a.versionId());m.put("name",v.get("name"));m.put("fileName",v.get("file_name"));m.put("extension",v.get("extension"));m.put("version",v.get("version_no"));m.put("size",v.get("size_bytes"));m.put("preview",v.get("preview_key")!=null);m.put("download",a.download());out.add(m);}return out;}
    public List<Map<String,Object>> learnerResources(String keyword){var result=new ArrayList<Map<String,Object>>();for(var course:learnerCourses("")){var detail=learnerDetail(course.get("id").toString());var merged=new LinkedHashMap<String,Map<String,Object>>();List<Map<String,Object>> attachments=new ArrayList<>((List<Map<String,Object>>)detail.get("attachments"));for(var lesson:(List<Map<String,Object>>)detail.get("lessons"))attachments.addAll((List<Map<String,Object>>)lesson.get("attachments"));for(var resource:attachments)merged.merge(resource.get("versionId").toString(),new LinkedHashMap<>(resource),(first,next)->{first.put("download",Boolean.TRUE.equals(first.get("download"))||Boolean.TRUE.equals(next.get("download")));return first;});for(var resource:merged.values()){if((keyword==null||(resource.get("name")+" "+resource.get("fileName")).contains(keyword))){var m=new LinkedHashMap<>(resource);m.put("courseId",course.get("id"));m.put("courseTitle",course.get("title"));m.put("category",course.get("category"));result.add(m);}}}return result;}
    Lesson lesson(Course c,String id){return list(c.lessons()).stream().filter(l->l.id().equals(id)).findFirst().orElseThrow(()->new ServiceException(404,"课时不存在"));}
    void materialAllowed(Course c,String version,String purpose){
        if("poster".equals(purpose)&&Objects.equals(c.coverVersionId(),version))return;
        for(var l:list(c.lessons())){if(Objects.equals(l.mainVersionId(),version)&&Set.of("play","preview","poster").contains(purpose))return;for(var a:list(l.attachments()))if(a.versionId().equals(version)&&("preview".equals(purpose)||"download".equals(purpose)&&a.download()))return;}
        for(var a:list(c.attachments()))if(a.versionId().equals(version)&&("preview".equals(purpose)||"download".equals(purpose)&&a.download()))return;
        throw new ServiceException(403,"课程不允许访问此资料或下载原件");
    }
}
